// Writes dist/_headers, the header file read by Cloudflare Pages and Netlify (same format on both).
// Runs at the end of every build, so the CSP hash always matches the build being deployed.
// S3/CloudFront ignores this file (deploy.sh does not upload it; headers come from the CloudFront policy).
import fs from 'node:fs';
import { securityHeaders } from './security-headers.mjs';
const h = securityHeaders();
const block = (path, pairs) => `${path}\n${Object.entries(pairs).map(([k, v]) => `  ${k}: ${v}`).join('\n')}\n`;
const out = [
  '# Generated by scripts/write-headers.mjs on every build. Do not edit by hand.',
  block('/*', { ...h, 'Cache-Control': 'public, max-age=0, must-revalidate' }),
  // Fingerprinted assets never change, so they can be cached for a year.
  block('/_astro/*', { 'Cache-Control': 'public, max-age=31536000, immutable' }),
].join('\n');
fs.writeFileSync('dist/_headers', out);
console.log(`write-headers: dist/_headers written (${Object.keys(h).length} security headers, CSP with ${h['Content-Security-Policy'].match(/sha256-/g)?.length ?? 0} script hash)`);
